  },
  "risks": {
    "weather": {
      "risk_summary": "August in Hangzhou typically has high temperatures and a chance of rain/typhoons. Several chosen POIs are outdoor-heavy (West Lake, Xixi Wetland) and marked as 'conditional' for rain and high temperature in the evidence. Lingyin and Qinghefang are more weather-resilient (mixed or suitable in rain).",
      "risk_days": [
        {
          "date": "2026-08-23",
          "risk_level": "moderate",
          "notes": "Possible high heat and showers — outdoor segments (West Lake, Xixi) may be uncomfortable; bring water, sun protection, and an umbrella."
        },
        {
          "date": "2026-08-24",
          "risk_level": "moderate",
          "notes": "Similar risks as previous day; plan flexible sequencing to move outdoor visits to clearer windows and favor indoor/mixed sites if heavy rain."
        }
      ],
      "adjustment_required": true,
      "adjustment_notes": "Plan flexible order to prioritize Lingyin and Qinghefang during heavy rain or extreme heat. Consider shortening outdoor walking loops, using covered/boat-based options at Xixi if available, and scheduling outdoor-heavy West Lake early morning or late afternoon to avoid peak heat."
